func (this *Deribit) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// fetchWithdrawals
	//
	//     {
	//         "address": "2NBqqD5GRJ8wHy1PYyCXTe9ke5226FhavBz",
	//         "amount": 0.5,
	//         "confirmed_timestamp": null,
	//         "created_timestamp": 1550571443070,
	//         "currency": "BTC",
	//         "fee": 0.0001,
	//         "id": 1,
	//         "priority": 0.15,
	//         "state": "unconfirmed",
	//         "transaction_id": null,
	//         "updated_timestamp": 1550571443070
	//     }
	//
	// fetchDeposits
	//
	//     {
	//         "address": "2N35qDKDY22zmJq9eSyiAerMD4enJ1xx6ax",
	//         "amount": 5,
	//         "currency": "BTC",
	//         "received_timestamp": 1549295017670,
	//         "state": "completed",
	//         "transaction_id": "230669110fdaf0a0dbcdc079b6b8b43d5af29cc73683835b9bc6b3406c065fda",
	//         "updated_timestamp": 1549295130159
	//     }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var currencyId any = this.SafeString(transaction, "currency")
	var code any = this.SafeCurrencyCode(currencyId, currency)
	var timestamp any = this.SafeInteger2(transaction, "created_timestamp", "received_timestamp")
	var updated any = this.SafeInteger(transaction, "updated_timestamp")
	var status any = this.ParseTransactionStatus(this.SafeString(transaction, "state"))
	var address any = this.SafeString(transaction, "address")
	var feeCost any = this.SafeNumber(transaction, "fee")
	var typeVar string = "deposit"
	var fee any = nil
	if IsTrue(!IsEqual(feeCost, nil)) {
		typeVar = "withdrawal"
		fee = map[string]any{
			"cost":     feeCost,
			"currency": code,
		}
	}
	return map[string]any{
		"info":        transaction,
		"id":          this.SafeString(transaction, "id"),
		"txid":        this.SafeString(transaction, "transaction_id"),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"address":     address,
		"addressTo":   address,
		"addressFrom": nil,
		"tag":         nil,
		"tagTo":       nil,
		"tagFrom":     nil,
		"type":        typeVar,
		"amount":      this.SafeNumber(transaction, "amount"),
		"currency":    code,
		"status":      status,
		"updated":     updated,
		"network":     nil,
		"internal":    nil,
		"comment":     nil,
		"fee":         fee,
	}
}
func (this *Deribit) ParsePosition(position any, optionalArgs ...any) any {
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "id": 404,
	//         "result": {
	//             "average_price": 0,
	//             "delta": 0,
	//             "direction": "buy",
	//             "estimated_liquidation_price": 0,
	//             "floating_profit_loss": 0,
	//             "index_price": 3555.86,
	//             "initial_margin": 0,
	//             "instrument_name": "BTC-PERPETUAL",
	//             "leverage": 100,
	//             "kind": "future",
	//             "maintenance_margin": 0,
	//             "mark_price": 3556.62,
	//             "open_orders_margin": 0.000165889,
	//             "realized_profit_loss": 0,
	//             "settlement_price": 3555.44,
	//             "size": 0,
	//             "size_currency": 0,
	//             "total_profit_loss": 0
	//         }
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var contract any = this.SafeString(position, "instrument_name")
	market = this.SafeMarket(contract, market)
	var side any = this.SafeString(position, "direction")
	side = Ternary(IsTrue((IsEqual(side, "buy"))), "long", "short")
	var unrealizedPnl any = this.SafeString(position, "floating_profit_loss")
	var initialMarginString any = this.SafeString(position, "initial_margin")
	var notionalString any = this.SafeString(position, "size_currency")
	var notionalStringAbs any = Precise.StringAbs(notionalString)
	var maintenanceMarginString any = this.SafeString(position, "maintenance_margin")
	return this.SafePosition(map[string]any{
		"info":                        position,
		"id":                          nil,
		"symbol":                      this.SafeString(market, "symbol"),
		"timestamp":                   nil,
		"datetime":                    nil,
		"lastUpdateTimestamp":         nil,
		"initialMargin":               this.ParseNumber(initialMarginString),
		"initialMarginPercentage":     this.ParseNumber(Precise.StringMul(Precise.StringDiv(initialMarginString, notionalStringAbs), "100")),
		"maintenanceMargin":           this.ParseNumber(maintenanceMarginString),
		"maintenanceMarginPercentage": this.ParseNumber(Precise.StringMul(Precise.StringDiv(maintenanceMarginString, notionalStringAbs), "100")),
		"entryPrice":                  this.SafeNumber(position, "average_price"),
		"notional":                    this.ParseNumber(notionalStringAbs),
		"leverage":                    this.SafeInteger(position, "leverage"),
		"unrealizedPnl":               this.ParseNumber(unrealizedPnl),
		"realizedPnl":                 this.SafeNumber(position, "realized_profit_loss"),
		"contracts":                   this.SafeNumber(position, "size"),
		"contractSize":                this.SafeNumber(position, "contractSize"),
		"marginRatio":                 nil,
		"liquidationPrice":            this.SafeNumber(position, "estimated_liquidation_price"),
		"markPrice":                   this.SafeNumber(position, "mark_price"),
		"lastPrice":                   nil,
		"collateral":                  nil,
		"marginMode":                  nil,
		"side":                        side,
		"percentage":                  nil,
		"hedged":                      nil,
		"stopLossPrice":               nil,
		"takeProfitPrice":             nil,
	})
}

